45	void NativePaddlePredictor::PrepareFeedFetch() {
46	  for (auto *op : inference_program_->Block(0).AllOps()) {
47	    if (op->Type() == "feed") {
48	      int idx = boost::get<int>(op->GetAttr("col"));
49	      if (feeds_.size() <= static_cast<size_t>(idx)) {
50	        feeds_.resize(idx + 1);
51	      }
52	      feeds_[idx] = op;
53	      feed_names_[op->Output("Out")[0]] = idx;
54	    } else if (op->Type() == "fetch") {
55	      int idx = boost::get<int>(op->GetAttr("col"));
56	      if (fetchs_.size() <= static_cast<size_t>(idx)) {
57	        fetchs_.resize(idx + 1);
58	      }
59	      fetchs_[idx] = op;
60	    }
61	  }
62	}
