131	bool NativePaddlePredictor::Run(const std::vector<PaddleTensor> &inputs,
132	                                std::vector<PaddleTensor> *output_data,
133	                                int batch_size) {
134	  if (UNLIKELY(config_.cpu_math_library_num_threads() > 1)) {
135	    paddle::platform::SetNumThreads(config_.cpu_math_library_num_threads());
136	  }
137	  VLOG(3) << "Predictor::predict";
138	  Timer timer;
139	  timer.tic();
140	  // set feed variable
141	  framework::Scope *scope = sub_scope_ != nullptr ? sub_scope_ : scope_.get();
142	  if (!SetFeed(inputs, scope)) {
143	    LOG(ERROR) << "fail to set feed";
144	    return false;
145	  }
146	  // Run the inference program
147	  // if share variables, we need not create variables
148	  VLOG(4) << "Run prepared context";
149	  executor_->RunPreparedContext(ctx_.get(), scope,
150	                                false, /* don't create local scope each time*/
151	                                false /* don't create variable each time */);
152	  VLOG(4) << "Finish prepared context";
153	  // get fetch variable
154	  if (!GetFetch(output_data, scope)) {
155	    LOG(ERROR) << "fail to get fetches";
156	    return false;
157	  }
158	  VLOG(3) << "predict cost: " << timer.toc() << "ms";
159	
160	  // For some other vector like containers not cleaned after each batch.
161	  tensor_array_batch_cleaner_.CollectNoTensorVars(scope_.get());
162	  tensor_array_batch_cleaner_.ResetNoTensorVars();
163	  return true;
164	}
