186	bool NativePaddlePredictor::SetFeed(const std::vector<PaddleTensor> &inputs,
187	                                    framework::Scope *scope) {
188	  VLOG(3) << "Predictor::set_feed";
189	  if (inputs.size() != feeds_.size()) {
190	    LOG(ERROR) << "wrong feed input size, need " << feeds_.size() << " but get "
191	               << inputs.size();
192	    return false;
193	  }
194	
195	  // Cache the inputs memory for better concurrency performance.
196	  feed_tensors_.resize(inputs.size());
